    v_lesson:=(x->>'lesson')::bigint;
    v_course:=(x->>'course')::integer;
    v_order:=(x->>'order')::integer;
    v_url:=x->>'url';
    IF v_url !~ '^https://www[.]youtube[.]com/watch[?]v=[A-Za-z0-9_-]{11}$' THEN
       RAISE EXCEPTION 'Invalid YouTube link: %',v_url;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM lms.lessons l JOIN lms.courses c ON c.course_id=l.course_id
                   WHERE l.lesson_id=v_lesson AND l.course_id=v_course AND l.lesson_order=v_order
                     AND l.is_published AND NOT l.is_deleted AND NOT c.is_deleted) THEN
       RAISE EXCEPTION 'Lesson not found or changed: %, %, %',v_course,v_lesson,v_order;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM lms.lesson_resources r WHERE r.lesson_id=v_lesson
      AND (upper(coalesce(r.resource_type,'')) IN ('VIDEO','YOUTUBE')
        OR coalesce(r.resource_url,'') ~* '(youtube[.]com|youtu[.]be)')) THEN
       INSERT INTO lms.lesson_resources(lesson_id,resource_type,title,resource_url,display_order)
       VALUES (v_lesson,'VIDEO','Video YouTube tham khảo theo chủ đề khóa học (cần kiểm tra độ khớp với bài)',v_url,
          (SELECT COALESCE(MAX(display_order),0)+1 FROM lms.lesson_resources WHERE lesson_id=v_lesson));
       v_count:=v_count+1;
    END IF;
 END LOOP;
 RAISE NOTICE 'New YouTube resource records added: %', v_count;
END $vedu$;
COMMIT;
